values
  ('1baa60e0-c420-5b63-bb38-f5b8c30a4862', null, (select id from public.skills where slug = 'read-g12-literary-structure-pov'), null, 'medium',
   $q$How does the structure of the third paragraph, in which Priya reports the water three times, add to the humor?$q$, $q$[{"text":"Each report repeats the same words exactly, so the paragraph shows Priya never worried.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Each report gives new scientific details, so the paragraph explains why boats leak.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"Each report is ignored by the coach, so the paragraph criticizes his leadership.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Each report is less calm than the last, so the repetition tracks the rising water and panic.","is_correct":true}]$q$::jsonb, $q$Each report is less calm than the last, so the repetition tracks the rising water and panic.$q$, $q$The repetition escalates, from "calmly" to "somewhat less calmly" to the water at their ankles, building comic tension. The coach does not appear in that paragraph at all.$q$, 'draft', 'fa642568-bf70-5126-804d-ecbee9e0b069')
